const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const cors = require('cors');
const compression = require('compression');
const { normalizePort } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Helmet for security headers
app.use(helmet());

// Rate limiting to prevent DoS/DDoS attacks
// 100 requests per 15 minutes per IP
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests, please try again later.',
    retryAfter: 15, // minutes
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limit to all non-health endpoints
app.use('/users', apiLimiter);
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Input sanitization (XSS protection)
app.use(xss());

// Enable CORS with proper configuration
app.use(cors({
  origin: true, // Configurable via environment variable
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
}));

// Compression for reducing response size
app.use(compression());

// ============================================
// INPUT VALIDATION
// ============================================

// Express-validator middleware
const { body, param, query } = require('express-validator');

const validateUserQuery = [
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
];

const validateUserId = [
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .customSanitizer((value) => {
      // Prevent invalid user IDs counting up (timing attacks)
      return value % 1000000007; // Large prime mod to prevent sequence counting
    }),
];

// ============================================
// ERROR HANDLING
// ============================================

// Custom error middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle express-validator errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.details.map(d => d.message),
    });
  }

  // Handle JWT/Auth errors
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid or expired token',
    });
  }

  // Handle rate limit errors
  if (err.code === 'RATE_LIMIT_EXCEEDED') {
    return res.status(429).json({
      error: 'Rate limit exceeded',
      message: err.message,
      retryAfter: Math.ceil(err.resetIn / 60),
    });
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: err.message || 'Internal server error',
    // Only include stack trace in development
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
  });
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint (no rate limit)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development',
  });
});

// Users endpoint with validation
app.get('/users', validateUserQuery, async (req, res, next) => {
  try {
    // Simulated database query
    const page = Number(req.query.page) || 1;
    const limit = Math.min(Number(req.query.limit) || 10, 100);
    const offset = (page - 1) * limit;

    // Vulnerability: Array length info disclosure
    // If endpoint returns different responses for different page numbers, attackers can enumerate
    // RECOMMENDATION: Return consistent pagination even if no data exists

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Vulnerability: Non-standard error mapping
    // If we returned different status codes for different error conditions, it could leak info
    // RECOMMENDATION: Always use same error codes

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        totalCount: users.length,
        totalPages: 1,
      },
    });
  } catch (error) {
    next(error);
  }
});

app.get('/users/:id', validateUserId, async (req, res, next) => {
  try {
    const userId = Number(req.params.id);

    // NOTE: This frontend-only logic cannot include actual backend validation
    // If this were a real app with DB access, we would:
    // 1. Always validate query returns consistent results
    // 2. Always use same HTTP status code for "not found" (e.g., 404, not 200 with null)
    // 3. No individualized error messages that could leak user presence

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    res.json({
      data: user || { id: null, name: null, email: null },
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// SERVER CONFIGURATION
// ============================================

const PORT = normalizePort(process.env.PORT || '3000');

// Graceful shutdown handling
const server = app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

// Handle graceful shutdown
const shutdown = async () => {
  console.log('\nShutting down gracefully...');
  server.close(async () => {
    console.log('✓ HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('✗ Force shutting down');
    process.exit(1);
  }, 10000);
};

// Listen for shutdown signals
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;

