# Security Improvements for app.js

## Core Issues Found

1. ✗ No input validation on endpoints
2. ✗ No error handling - crashes expose stack traces
3. ✗ No rate limiting - vulnerable to Denial of Service
4. ✗ No request body parsing middleware
5. ✗ Missing security headers
6. ✗ No input sanitization
7. ✗ No environment variable validation
8. ✗ Missing validation of user-provided data
9. ✗ No Content Security Policy (CSP)
10. ✗ No X-Frame-Options header

## Security Enhancement Checklist

✓ Add robust error handling with structured logging
✓ Implement input validation using express-validator
✓ Add rate limiting (express-rate-limit)
✓ Set security headers (helmet)
✓ Implement input sanitization (dompurify or custom)
✓ Validate environment variables
✓ Add request validation middleware
✓ Implement validation on all user inputs
✓ Add Content Security Policy
✓ Set X-Frame-Options and other security headers
✓ Implement error response standardization
✓ Add request body size limits
✓ Implement timeout handling

---

# Enhanced Implementation

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');           // Security headers
const rateLimit = require('express-rate-limit'); // DOS protection
const expressValidator = require('express-validator'); // Input validation
const morgan = require('morgan');          // Request logging
const { body, query, validationResult } = expressValidator;

const app = express();

// ============================
// Configuration
// ============================
const allowedOrigins = process.env.ALLOWED_ORIGINS
  ? process.env.ALLOWED_ORIGINS.split(',')
  : ['http://localhost:3000'];

// ============================
// Security Middleware
// ============================

// Rate limiting for all routes (except health check)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  // Skip health check endpoint from rate limiting
  skip: (req) => req.path === '/health',
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  // Log rate limit hits
  handler: (req, res) => {
    console.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({ error: 'Too many requests' });
  }
});

app.use(limiter);

// Security headers
app.use(helmet({
  crossOriginResourcePolicy: { policy: 'same-site' },
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      mediaSrc: ["'self'"],
      objectSrc: ["'none'"],
    },
  },
}));

// Request body size limit (prevents memory exhaustion attacks)
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: false, limit: '1mb' }));

// CORS configuration
app.use((req, res, next) => {
  const origin = req.headers.origin || '';
  if (allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin);
    res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    res.header('Access-Control-Allow-Credentials', 'true');
  }
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Request logging (for debugging and attack detection)
app.use(morgan('combined', {
  skip: (req) => req.path === '/health',
  stream: {
    write: (message) => console.log(message.trim())
  }
}));

// ============================
// Input Validation Middleware
// ============================

// Validate user data
const validateUserData = [
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .escape(), // Escape potential HTML entities
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
];

// Validate query parameters
const validateQueryParams = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
];

// ============================
// Custom Error Classes
// ============================

class AppError extends Error {
  constructor(message, statusCode = 500, code = 'INTERNAL_ERROR') {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message, details = []) {
    super(message, 400, 'VALIDATION_ERROR');
    this.details = details;
  }
}

class RateLimitError extends AppError {
  constructor() {
    super('Too many requests', 429, 'RATE_LIMIT_EXCEEDED');
  }
}

class ResourceNotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404, 'RESOURCE_NOT_FOUND');
  }
}

// ============================
// Error Handling Middleware
// ============================

const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;

  // Log error details
  console.error('Error occurred:', {
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString()
  });

  // Handle specific Express validation errors
  if (err instanceof expressValidator.ValidationError) {
    const details = err.array().map(item => ({
      field: item.path,
      message: item.msg,
      type: item.type
    }));

    error = new ValidationError('Validation failed', details);
  }

  // Handle rate limit errors
  if (err.code === 'RATE_LIMIT_EXCEEDED') {
    error = new RateLimitError();
  }

  // Mongoose cast errors (MongoDB)
  if (err.name === 'CastError' && err.kind === 'ObjectId') {
    error = new ResourceNotFoundError('Resource');
  }

  // Mongoose duplicate key errors
  if (err.code === 11000) {
    error = new ValidationError('Duplicate field value entered', [
      { field: 'email', message: 'This email is already registered' }
    ]);
  }

  // Mongoose validation errors
  if (err.name === 'ValidationError') {
