app.get('/users', (req, res, next) => {
  try {
    const { email } = req.query;

    // Validate email parameter if provided
    if (email && !validateUserEmail(email)) {
      logger.warn(`Invalid email format: ${email} from ${req.ip}`);
      return res.status(400).json({
        error: 'Invalid email parameter',
        message: 'Please provide a valid email address'
      });
    }

    // Sanitize output - don't expose internal data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    // Filter by email if provided
    const filteredUsers = email
      ? users.filter(user => validator.isEmail(user.email) &&
        user.email.toLowerCase().includes(email.toLowerCase()))
      : users;

    res.json({
      data: filteredUsers,
      metadata: {
        total: filteredUsers.length,
        filtered: !!email
      }
    });
  } catch (error) {
    logger.error('Users endpoint error:', error);
    next(error);
  }
});

// Catch-all error handler
app.use((err, req, res, next) => {
  // Log error details
  logger.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

  // Return appropriate error response
  const statusCode = err.statusCode || err.status || 500;
  const message = err.message || 'Internal server error';

  res.status(statusCode).json({
    error: message,
    code: statusCode,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

