// Secure Express application with robust error handling and input validation
// This version implements security best practices for production use

const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const xss = require('xss-clean'); // XSS protection
const morgan = require('morgan'); // HTTP request logging
const { body, query, validationResult } = require('express-validator'); // Input validation

const app = express();

// =============================================================================
// MIDDLEWARE CONFIGURATION
// =============================================================================

// Security middleware
app.use(helmet()); // Set various HTTP headers for security
app.use(xss()); // Sanitize input data to prevent XSS

// Rate limiting - protect API endpoints from abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 60
  },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Request logging
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode >= 400 // Log only 4xx/5xx errors
}));

// Trust proxy settings (remove for local development)
app.set('trust proxy', 1);

// Body parsing - enforce size limit
app.use(express.json({ limit: '10kb' }));

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

/**
 * Middleware to handle validation errors
 * For production, you might want to send structured error responses
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const errorMsg = errors.array().map(err => err.msg).join(', ');
    return res.status(400).json({
      success: false,
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

/**
 * Global error handler
 * Always keep this as the last middleware in the chain
 */
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err);

  // Default error response
  let statusCode = 500;
  let error = 'Internal server error';
  let details = null;

  // Mongoose errors
  if (err.name === 'ValidationError') {
    statusCode = 400;
    error = 'Validation error';
    details = Object.values(err.errors).map(v => v.message);
  }
  // Cast errors (e.g., malformed ObjectId)
  else if (err.name === 'CastError') {
    statusCode = 400;
    error = 'Invalid ID format';
    details = err.message;
  }
  // JWT errors
  else if (err.name === 'JsonWebTokenError') {
    statusCode = 401;
    error = 'Invalid token';
  }
  // Other errors
  else if (err.message) {
    statusCode = err.statusCode || statusCode;
    error = err.message;
  }

  // Production: don't expose internal stack traces
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(statusCode).json({
    success: false,
    error,
    ...(details && { details }),
    ...(isDevelopment && { stack: err.stack })
  });
};

// =============================================================================
// ROUTES
// =============================================================================

// Health check endpoint with input validation
app.get('/health', [
  query('ping').optional().trim().escape(), // Sanitize optional ping parameter
], validateRequest, (req, res) => {
  // Validate results here if needed
  const { ping } = req.query;

  res.json({
    success: true,
    status: 'ok',
    timestamp: new Date().toISOString(),
    ...(ping && { ping: `Pong: ${ping}` })
  });
});

// Users endpoint with comprehensive input validation
app.get('/users', [
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('search').optional().trim().escape().isLength({ max: 500 }).withMessage('Search term too long'),
  query('sort').optional().custom(value => {
    const allowedSortFields = ['id', 'name', 'email', '-name'];
    if (!allowedSortFields.includes(value)) {
      throw new Error('Invalid sort field');
    }
    return true;
  }).withMessage('Invalid sort field'),
], validateRequest, (req, res) => {
  const { page = 1, limit = 10, search, sort = 'id' } = req.query;

  // Parse and validate pagination
  const pageNum = parseInt(page);
  const limitNum = Math.min(parseInt(limit), parseInt(process.env.MAX_RESULTS_PER_PAGE) || 100);

  // Simulated user data set
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' },
    { id: 5, name: 'Eve', email: 'eve@example.com' },
  ];

  // Simple filter based on search
  const filteredUsers = search
    ? users.filter(user =>
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
      )
    : users;

  // Sorting (simple implementation)
  const [sortField, sortDirection] = sort.split(':');
  const sortedUsers = filteredUsers.sort((a, b) => {
    const aVal = a[sortField] || '';
    const bVal = b[sortField] || '';
    return sortDirection === '-' ? bVal.localeCompare(aVal) : aVal.localeCompare(bVal);
  });

  // Pagination
  const startIndex = (pageNum - 1) * limitNum;
  const paginatedUsers = sortedUsers.slice(startIndex, startIndex + limitNum);

  res.json({
    success: true,
    data: paginatedUsers,
    pagination: {
      page: pageNum,
      limit: limitNum,
      total: filteredUsers.length,
      totalPages: Math.ceil(filteredUsers.length / limitNum)
    }
  });
});

// POST endpoint (example) for creating users
app.post('/users', [
  body('name').trim().escape().isLength({ min: 1, max: 100 }).withMessage('Name is required and must be 1-100 characters'),
  body('email')
    .trim()
    .escape()
    .isEmail({ ignore_max_length: true })
    .normalizeEmail()
    .withMessage('Invalid email format'),
], validateRequest, (req, res) => {
  const { name, email } = req.body;

  // In production, this would validate against database
  res.status(201).json({
    success: true,
    message: 'User created successfully',
    data: {
      id: Date.now(),
      name,
      email,
      createdAt: new Date().toISOString()
    }
  });
});

// =============================================================================
// ERROR HANDLING
// =============================================================================

// 404 handler - must be added after all routes
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Route not found',
    path: req.path
  });
});

// Global error handler - must be last
app.use(errorHandler);

// =============================================================================
// SERVER STARTUP
// =============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  console.log(`Server running in ${NODE_ENV} mode on port ${PORT}`);
  console.log(`Health check: http://localhost:${PORT}/health`);
  console.log(`Users endpoint: http://localhost:${PORT}/users`);
});

module.exports = app;

