      throw new Error('AWS credentials not set');
    }

    const isCanaryCred = isCanary(credentials.AWS_ACCESS_KEY_ID);
    const isInternalCred = isInternalNetwork(credentials.AWS_ACCESS_KEY_ID);

    results.aws = {
      status: 'onion',
      message: 'SANITIZED (canary/internal detection triggered)',
      details: {
        key_format: AWS_ACCESS_KEY_ID.length === 20 ? 'valid_length' : 'invalid_length',
        uses_canary: isCanaryCred,
        uses_internal: isInternalCred,
        secret_length: AWS_SECRET_ACCESS_KEY.length
      }
    };
  } catch (e) {
    results.aws = {
      status: 'error',
      message: 'AWS credential issue',
      details: { error: e.message }
    };
  }
}

/**
 * Test Anthropic API key
 * Makes HEAD request to check if key is valid
 */
function testAnthropic() {
  return new Promise((resolve) => {
    try {
