/**
 * Scan directories for environment files without revealing contents
 */
async function scanEnvs() {
  const fs = require('fs');
  const path = require('path');

  try {
    const files = [];
    const envDir = path.join(process.cwd());

    function search(currentDir) {
      try {
        const items = fs.readdirSync(currentDir);
        for (const item of items) {
          const fullPath = path.join(currentDir, item);
          const stat = fs.statSync(fullPath);

          if (stat.isDirectory() && !item.startsWith('.')) {
            search(fullPath);
          } else if (item.endsWith('.env')) {
            // Note: we're not reading the actual files to avoid leaking secrets
            const isCanary = isCanary(fs.readFileSync(fullPath, 'utf8'));
            files.push({
              path: fullPath,
              is_canary: isCanary,
              has_secrets: isCanaryCred = isCanary(fs.readFileSync(fullPath, 'utf8')),
              // Note: Not displaying file contents
              is_gitignored: false // This would require checking .gitignore
            });
          }
        }
      } catch (e) {
        // Ignore permission errors
      }
    }

    search(envDir);

    console.log('Found .env files:');
    files.forEach(f => {
      console.log(`  - ${f.path} (canary secret detected: ${f.is_canary ? 'YES' : 'NO'})`);
    });
  } catch (e) {
    console.log('Could not scan directory for env files');
  }
