// Secure Express application with proper error handling and input validation
// Focus: Security best practices for vulnerability protection

const express = require('express');
const app = express();

// Enable trust proxy (needed if behind a reverse proxy/load balancer)
app.set('trust proxy', 1);

// ===== SECURITY MIDDLEWARE =====

// Parse JSON with size limits (prevents memory exhaustion DoS attacks)
app.use(express.json({ limit: '100kb' }));
app.use(express.urlencoded({ extended: true, limit: '100kb' }));

// Security headers middleware
const securityHeaders = (req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
};
app.use(securityHeaders);

// Rate limiting middleware (protect against brute force)
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Request logging middleware
const morgan = require('morgan');
const logger = morgan('combined', {
  skip: (req, res) => process.env.NODE_ENV === 'test'
});
app.use(logger);

// ===== INPUT VALIDATION & SANITIZATION =====

// Validate and sanitize email addresses
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// Validate non-empty strings
function isValidString(str, minLength = 1, maxLength = 255) {
  return typeof str === 'string' &&
         str.length >= minLength &&
         str.length <= maxLength &&
         !str.includes('..'); // Prevent path traversal
}

// Escape HTML to prevent XSS attacks
function escapeHtml(text) {
  if (typeof text !== 'string') return text;
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// Validate and sanitize user input
function sanitizeUserInput(userData) {
  const sanitized = {
    name: null,
    email: null
  };

  // Validate name
  if (userData.name && isValidString(userData.name.trim(), 2, 50)) {
    sanitized.name = escapeHtml(userData.name.trim());
  }

  // Validate email
  if (userData.email && isValidEmail(userData.email.trim())) {
    sanitized.email = userData.email.trim().toLowerCase();
  }

  return sanitized;
}

// ===== ROUTES =====

// Health check endpoint with rate limiting disabled for monitoring
app.get('/health', (req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Get users endpoint
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit, offset } = req.query;

    // Validate limit parameter
    let parsedLimit = parseInt(limit);
    if (limit && (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be a number between 1 and 100.'
      });
    }

    // Validate offset parameter
    let parsedOffset = parseInt(offset);
    if (offset && (isNaN(parsedOffset) || parsedOffset < 0)) {
      return res.status(400).json({
        error: 'Invalid offset parameter. Must be a non-negative number.'
      });
    }

    // Apply limits
    parsedLimit = Math.min(Math.max(parsedLimit || 10, 1), 100);
    parsedOffset = parsedOffset || 0;

    // Return sanitized mock data (in production, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: users.length
      }
    });

  } catch (error) {
    console.error('Error retrieving users:', error);
    res.status(500).json({
      error: 'An error occurred while processing your request'
    });
  }
});

// ===== ERROR HANDLING =====

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error details for debugging
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Send appropriate error response
  const statusCode = err.statusCode || err.status || 500;
  const response = {
    error: err.message || 'Internal server error',
    timestamp: new Date().toISOString()
  };

  // Do not expose sensitive details in production
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // In production, you might want to gracefully shutdown or notify monitoring
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// ===== SERVER CONFIGURATION =====

let server;
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const startServer = () => {
  server = app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });

  // Graceful shutdown
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Exiting gracefully...`);
    if (server) {
      server.close(() => {
        console.log('Server closed.');
        process.exit(0);
      });
    }
    // Force exit after 10 seconds (for situations like SIGKILL)
    setTimeout(() => {
      console.error('Forcing server shutdown after timeout.');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));
};

// Start server only if not in test mode
if (process.env.NODE_ENV !== 'test') {
  startServer();
}

module.exports = app;

