// Improved application with robust error handling and security
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const morgan = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================
// Security headers
app.use(helmet({
  contentSecurityPolicy: process.env.NODE_ENV === 'production',
  crossOriginEmbedderPolicy: process.env.NODE_ENV === 'production',
  crossOriginOpenerPolicy: process.env.NODE_ENV === 'production',
  crossOriginResourcePolicy: { policy: "same-site" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  reframedCSP: true,
  xssFilter: true
}));

// Rate limiting - prevents brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Allow health checks
  handler: (req, res, next, options) => {
    res.status(429).json(options.message);
  }
});

// Apply rate limiting to all routes
app.use(limiter);

// Body size limits (prevents buffer overflow)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL injection and XSS
app.use(mongoSanitize());
app.use(xss());

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================
// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle known errors
  if (err.name === 'ValidationError') {
    res.status(400).json({
      error: 'Validation Error',
      message: err.message
    });
    return;
  }

  if (err.code === 'ECONNREFUSED' || err.code === 'EADDRINUSE') {
    res.status(503).json({
      error: 'Service Unavailable',
      message: 'Service or database is temporarily unavailable'
    });
    return;
  }

  // Generic error response
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal Server Error',
    type: err.type || 'server_error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// REQUEST VALIDATION
// ============================================
const validateHealthRequest = (req, res, next) => {
  // No parameters to validate for health endpoint
  next();
};

const validateUsersQuery = (req, res, next) => {
  // Validate query parameters are safe
  const allowedFields = ['name', 'email', 'id'];
  const invalidFields = Object.keys(req.query).filter(
    field => !allowedFields.includes(field)
  );

  if (invalidFields.length > 0) {
    return res.status(400).json({
      error: 'Bad Request',
      message: `Invalid query parameters: ${invalidFields.join(', ')}`
    });
  }

  next();
};

// ============================================
// ROUTES
// ============================================
app.get('/health', (req, res) => {
  // Validate request
  validateHealthRequest(req, res, () => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  });
});

app.get('/users', (req, res) => {
  const allowedFilters = ['name', 'email', 'id'];
  const filters = Object.keys(req.query)
    .filter(key => allowedFilters.includes(key))
    .reduce((acc, key) => {
      acc[key] = req.query[key];
      return acc;
    }, {});

  // Simulate database query with validation
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply filters if provided
  const filteredUsers = users.filter(user => {
    return Object.entries(filters).every(([key, value]) => {
      return user[key]?.toString().toLowerCase() === value.toLowerCase();
    });
  });

  res.json({
    data: filteredUsers,
    count: filteredUsers.length,
    filtersApplied: Object.keys(filters).length > 0
  });
});

// ============================================
// START SERVER WITH ERROR HANDLING
// ============================================
const PORT = process.env.PORT || 3000;

const startServer = async () => {
  try {
    // Validate environment
    if (!process.env.NODE_ENV) {
      console.warn('⚠️ Warning: NODE_ENV is not set. Using default: development');
    }

    app.listen(PORT, () => {
      console.log('🚀 Server running on port', PORT);
      console.log('🌍 Environment:', process.env.NODE_ENV || 'development');
      console.log('🔒 Security features enabled:');
      console.log('  ✓ Helmet security headers');
      console.log('  ✓ Rate limiting');
      console.log('  ✓ XSS protection');
      console.log('  ✓ NoSQL injection prevention');
    });
  } catch (error) {
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
};

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('💥 Uncaught Exception:', err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('💥 Unhandled Rejection at:', promise, 'reason:', reason);
  // Don't exit immediately for rejection - let graceful shutdown handle it
});

// Graceful shutdown
const gracefulShutdown = async (signal) => {
  console.log(`\n🛑 ${signal} received. Starting graceful shutdown...`);

  try {
    // Close server
    app.close(() => {
      console.log('✅ Express server closed');
      process.exit(0);
    });
  } catch (err) {
    console.error('Error during shutdown:', err);
    process.exit(1);
  }
};

// Listen for shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Start the server
startServer();

module.exports = app;

